var T = new Date(), yr = T.getFullYear();
var start = new Date(yr, 0, 1), end = new Date(yr + 1, 0, 1);
var days = Math.ceil((end - start) / 86400000), passed = Math.max(0, Math.min(days, Math.floor((T - start) / 86400000)));
var rest = days - passed;
Crowd.units(el, { total: days, used: passed, unit: '日',
title: yr + '年の' + days + '日を玉で並べると',
